/* ============================================================
   座席の実座標（KINEZO 座席図の data-coords）と実測したスクリーン中心
   ------------------------------------------------------------
   取得日: 2026-09-03  取得元: 各シアターの choice_seat ページ（公開・認証不要）
   対象: T・ジョイ横浜 / 新宿バルト9 / T・ジョイ京都 / T・ジョイ梅田 / 横浜ブルク13
   - seats[席ID] = [x, y] … 座席図PNG上の席の中心（px）。x=左右, y=前後（小さいほど前）
   - screenCenterX … 「スクリーンの中心」として使う x（px）
       centerSource=screenbar : 座席図PNGに描かれた SCREEN バー（高さ約10px・灰色）の左右端を
                                画素解析して求めた中心。席ブロックが片側に偏っている小部屋でも
                                スクリーン基準で正しく測れる（barDevSeats = 席範囲中心との差・席単位）
       centerSource=extent    : SCREEN バーを検出できなかった図（白い帯を誤検出するケースを除外）では
                                全席の左端〜右端の中心。実バーが取れた約40スクリーンで両者は
                                0.01〜0.04席以内で一致していたため、妥当な代替
   - pitchX … 同列で隣接する席の中心間隔の中央値（px）＝「1席分」
   - minX/maxX, yFront/yBack … 全席の範囲（px）
   これは映画館が公開している座席図（模式図）に基づく相対位置であり、実寸（m）や床の傾斜は含まない。
   推定値は一切入れていない。座標があるシアターではエンジンは席番号グリッドではなくこちらを使う。
   ============================================================ */
